import std.io : println;
import std.fs : readToString; 
import std.net.http; 

const int PORT = 8080;

void index_requests(Server* server) {
  server
    .get("/") { auto it -> it.response("./pages/index.html".readToStringOr("Page not found")); }
    .post("/") { auto it -> it.respomse(); }; 
}

type Fn = void(Server*); 

void main() {
  auto server = Server::new(PORT); 

  Fn[] arr = [index_requests];

  for (int i = 0; i < arr.length; ++i) {
    Fn fn = arr[i];
    fn(&server);
  }

  server
    .start();
}
